#ifndef COURSES_HPP
#define COURSES_HPP

#include <iostream>
#include <vector>
#include <string>
#include <fstream>
#include <cmath>
#include <algorithm>
#include <cctype>
#include <sstream>
#include "general_functions.hpp"

using namespace std;

struct Post
{
    int id;
    string title;
    string message;
    string course_inf;
};

struct Notification
{
    string id;
    string name;
    string message;
};

struct TA_Request
{
    int form_id
}

struct Lesson
{
    int id;
    string name;
    int credit;
    int prerequisite;
    vector<int> major_ids;
};

class Course
{
public:
    Course(int i, string cn, int c, string pi, string pn, string t, string ed, int cu, int p, vector<int>mi);
    void view_all_lessons();
    void view_the_specific_lesson();
    string create_course_inf();
    int get_id() { return id; }
    string get_name() { return name; }
    int get_prerequisite() { return prerequisite; }
    string get_professor_id() { return professor_id; }
    string get_time() { return time; }
    string get_exam_date() { return exam_date; }
    vector<int> get_major_ids() { return major_ids; }

private:
    int id;
    string name;
    int capacity;
    string professor_id;
    string professor_name;
    string time;
    string exam_date;
    int class_number;
    int prerequisite;
    vector<int> major_ids;
};

#endif
